// who-line hero runtime — extracted from Portfolio/who-line/index.html.
// Base generated by scripts/build-who-line-runtime.mjs; intro customized:
// settle the write-on instantly, fade the copy in, then play the design→build
// hover-icon sequence (hover still works after).
//
// Ported vanilla JS: it is untyped by nature and checking it would only produce
// implicit-any noise over code that is not maintained here.
// @ts-nocheck
/* eslint-disable */
import { GLYPHS } from './whoLineGlyphs';

/**
 * Boots the hero: settled lockup + fade-in copy + hover-icon intro sequence.
 * Returns a cleanup for React's effect.
 */
export function initWhoLine(): () => void {
  let disposed = false;
  const ac = new AbortController();

      // ------------------------------------------------------------------
      // Design write-on (pen + letters + underline) — same engine as design-hover
      // ------------------------------------------------------------------
      const cfg = {
        duration: 1200,
        startDelay: 100,
        letterGap: 46,
        holdEnd: 900,
        lastLetterSpeed: 4,
        ex1: 0.5,
        ey1: 0,
        ex2: 0.8,
        ey2: 1,
        letterEase: 0.35,
        letterFade: 100,
        fadeOffset: 0,
        letterRise: 0.5,
        letterBlur: 0.25,
        strokeLead: 1,
        strokeSoft: 1.2,
        strokeOpacity: 1,
        penSize: 16,
        penSmooth: 200,
        penLift: 0.5,
        tiltGain: 0.85,
        tiltMax: 22,
        penTilt: 0,
        penOffsetX: 3,
        penOffsetY: -2,
        penExit: 240,
      };

      function cubicBezier(x1, y1, x2, y2) {
        const ax = 3 * x1 - 3 * x2 + 1;
        const bx = 3 * x2 - 6 * x1;
        const cx = 3 * x1;
        const ay = 3 * y1 - 3 * y2 + 1;
        const by = 3 * y2 - 6 * y1;
        const cy = 3 * y1;
        const sampleX = (t) => ((ax * t + bx) * t + cx) * t;
        const slopeX = (t) => (3 * ax * t + 2 * bx) * t + cx;
        return function ease(x) {
          if (x <= 0) return 0;
          if (x >= 1) return 1;
          let t = x;
          for (let i = 0; i < 8; i += 1) {
            const dx = sampleX(t) - x;
            if (Math.abs(dx) < 1e-6) break;
            const d = slopeX(t);
            if (Math.abs(d) < 1e-6) break;
            t -= dx / d;
          }
          return ((ay * t + by) * t + cy) * t;
        };
      }

      function invertEase(ease, y) {
        if (y <= 0) return 0;
        if (y >= 1) return 1;
        let lo = 0;
        let hi = 1;
        for (let i = 0; i < 30; i += 1) {
          const mid = (lo + hi) / 2;
          if (ease(mid) < y) lo = mid;
          else hi = mid;
        }
        return (lo + hi) / 2;
      }

      const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);
      const lerp = (a, b, t) => a + (b - a) * t;
      const smoothstep = (t) => t * t * (3 - 2 * t);
      const easeOutCubic = (t) => 1 - Math.pow(1 - t, 3);

      const WORD = GLYPHS.word;
      const WORD_WIDTH = WORD.letters[WORD.letters.length - 1].end;
      const UNDER = GLYPHS.underline;
      const UNDER_WIDTH = 56.218;
      const UNDER_DX = -0.129;
      const UNDER_DY = 15.94;
      // The swash is drawn for the 55-wide "design"; stretch it across the added "s".
      const UNDER_SX = WORD_WIDTH / 55;
      const PEN = GLYPHS.pen;
      const PEN_BOX = 16;
      const TIP = { x: PEN.nib.x, y: PEN.nib.y };
      const VIEW = { x: -3, y: -3, w: 80 + (WORD_WIDTH - 55), h: 30 };

      function buildTimeline() {
        const letters = WORD.letters;
        const gaps = cfg.letterGap * (letters.length - 1);
        const inkTime = Math.max(cfg.duration - gaps, 120);
        const ease = cubicBezier(cfg.ex1, cfg.ey1, cfg.ex2, cfg.ey2);
        const weights = letters.map((letter, i) => {
          const span = Math.max(letter.end - letter.start, 0.01);
          return i === letters.length - 1 ? span / Math.max(cfg.lastLetterSpeed, 0.5) : span;
        });
        const weightSum = weights.reduce((a, b) => a + b, 0);
        const segments = [];
        let t = 0;
        letters.forEach((letter, i) => {
          const dur = inkTime * (weights[i] / weightSum);
          segments.push({ letter, i, t0: t, t1: t + dur, x0: letter.start, x1: letter.end });
          t += dur;
          if (i < letters.length - 1) {
            segments.push({
              gap: true,
              t0: t,
              t1: t + cfg.letterGap,
              x0: letter.end,
              x1: letter.end,
            });
            t += cfg.letterGap;
          }
        });
        const total = t || 1;
        const triggers = segments
          .filter((s) => !s.gap)
          .map((s) => cfg.duration * invertEase(ease, s.t1 / total));
        return { segments, total, ease, triggers };
      }

      const timeline = buildTimeline();

      function buildStrokePath() {
        const W = 280;
        const H = 48;
        const points = [];
        const canvas = document.createElement("canvas");
        canvas.width = W;
        canvas.height = H;
        const ctx = canvas.getContext("2d", { willReadFrequently: true });
        const sx = W / UNDER_WIDTH;
        const sy = H / 8.70068;
        ctx.setTransform(sx, 0, 0, sy, 0, 0);
        ctx.fillStyle = "#000";
        ctx.fill(new Path2D(UNDER.d));
        const ys = new Float64Array(W);
        const ok = new Uint8Array(W);
        const pixels = ctx.getImageData(0, 0, W, H).data;
        for (let x = 0; x < W; x += 1) {
          let top = -1;
          let bot = -1;
          for (let y = 0; y < H; y += 1) {
            if (pixels[(y * W + x) * 4 + 3] > 20) {
              if (top < 0) top = y;
              bot = y;
            }
          }
          if (top >= 0) {
            ys[x] = ((top + bot) * 0.5) / sy;
            ok[x] = 1;
          }
        }
        let last = ys[0] || 4;
        for (let x = 0; x < W; x += 1) {
          if (ok[x]) last = ys[x];
          else ys[x] = last;
        }
        for (let x = W - 1; x >= 0; x -= 1) {
          if (ok[x]) last = ys[x];
          else ys[x] = last;
        }
        const radius = 18;
        for (let x = 0; x < W; x += 1) {
          let sum = 0;
          let wsum = 0;
          for (let k = -radius; k <= radius; k += 1) {
            const j = Math.max(0, Math.min(W - 1, x + k));
            const weight = Math.exp((-0.5 * k * k) / ((radius * 0.45) ** 2));
            sum += ys[j] * weight;
            wsum += weight;
          }
          points.push({ x: (x / (W - 1)) * UNDER_WIDTH, y: sum / wsum });
        }
        let d = "";
        for (let i = 0; i < points.length; i += 2) {
          const pt = points[i];
          d += i === 0 ? `M${pt.x.toFixed(3)} ${pt.y.toFixed(3)}` : `L${pt.x.toFixed(3)} ${pt.y.toFixed(3)}`;
        }
        const end = points[points.length - 1];
        d += `L${end.x.toFixed(3)} ${end.y.toFixed(3)}`;
        return d;
      }

      const measureRoot = document.createElementNS("http://www.w3.org/2000/svg", "svg");
      measureRoot.setAttribute("width", "0");
      measureRoot.setAttribute("height", "0");
      measureRoot.style.cssText = "position:absolute;width:0;height:0;overflow:hidden";
      const strokeLine = document.createElementNS("http://www.w3.org/2000/svg", "path");
      strokeLine.setAttribute("d", buildStrokePath());
      measureRoot.appendChild(strokeLine);
      document.body.appendChild(measureRoot);
      const totalLen = strokeLine.getTotalLength();

      function nibAt(p) {
        const len = totalLen * clamp01(p);
        const d = Math.min(1.2, totalLen / 2);
        const a = strokeLine.getPointAtLength(Math.max(0, len - d));
        const b = strokeLine.getPointAtLength(Math.min(totalLen, len + d));
        const here = strokeLine.getPointAtLength(len);
        const slope = (Math.atan2(b.y - a.y, b.x - a.x) * 180) / Math.PI;
        return {
          x: UNDER_DX + here.x * UNDER_SX,
          y: UNDER_DY + here.y,
          rot: Math.max(-cfg.tiltMax, Math.min(cfg.tiltMax, slope * cfg.tiltGain)),
        };
      }

      function progressForX(wordX) {
        const target = (wordX / WORD_WIDTH) * UNDER_WIDTH;
        let lo = 0;
        let hi = totalLen;
        for (let i = 0; i < 24; i += 1) {
          const mid = (lo + hi) / 2;
          if (strokeLine.getPointAtLength(mid).x < target) lo = mid;
          else hi = mid;
        }
        return (lo + hi) / 2 / Math.max(totalLen, 1e-6);
      }

      function rawHead(timeMs) {
        const t = Math.max(0, timeMs - cfg.startDelay);
        const s = clamp01(t / cfg.duration);
        const warped = timeline.ease(s) * timeline.total;
        let headX = WORD_WIDTH;
        let gapLift = 0;
        for (const seg of timeline.segments) {
          if (warped > seg.t1) continue;
          const span = Math.max(seg.t1 - seg.t0, 1e-6);
          const local = clamp01((warped - seg.t0) / span);
          if (seg.gap) {
            headX = seg.x1;
            gapLift = Math.sin(Math.PI * local);
          } else {
            headX = lerp(seg.x0, seg.x1, lerp(local, smoothstep(local), cfg.letterEase));
          }
          break;
        }
        return { headX, gapLift };
      }

      function smoothHead(timeMs) {
        if (cfg.penSmooth <= 0) return rawHead(timeMs);
        let headX = 0;
        let gapLift = 0;
        let total = 0;
        for (let i = 0; i < 9; i += 1) {
          const k = (i / 8) * 2 - 1;
          const weight = Math.exp(-4 * k * k);
          const at = rawHead(timeMs + k * cfg.penSmooth * 0.5);
          headX += at.headX * weight;
          gapLift += at.gapLift * weight;
          total += weight;
        }
        return { headX: headX / total, gapLift: gapLift / total };
      }

      function sample(timeMs) {
        const { headX, gapLift } = smoothHead(timeMs);
        const nib = nibAt(progressForX(headX));
        const letters = WORD.letters.map((letter, i) => {
          const settled = timeline.triggers[i] + cfg.startDelay + cfg.fadeOffset;
          const fade = easeOutCubic(
            clamp01((timeMs - (settled - cfg.letterFade)) / cfg.letterFade)
          );
          return {
            opacity: fade,
            dy: cfg.letterRise * (1 - fade),
            blur: cfg.letterBlur * (1 - fade),
          };
        });
        const revealX = (nib.x - UNDER_DX) / UNDER_SX + cfg.strokeLead;
        const done = clamp01(
          (timeMs - cfg.startDelay - cfg.duration) / Math.max(cfg.penExit, 1)
        );
        const exit = cfg.penExit > 0 ? easeOutCubic(done) : 0;
        const penScale = cfg.penSize / PEN_BOX;
        const restX = GLYPHS.figma.penRestX + (WORD_WIDTH - 55) + TIP.x * penScale;
        const restY = GLYPHS.figma.penRestY + TIP.y * penScale;
        return {
          revealX,
          letters,
          pen: {
            x: lerp(nib.x + cfg.penOffsetX, restX, exit),
            y: lerp(nib.y + cfg.penOffsetY - gapLift * cfg.penLift, restY, exit),
            rot: cfg.penTilt + nib.rot * (1 - exit),
            opacity: 1,
            scale: penScale,
          },
        };
      }

      const SVG_NS = "http://www.w3.org/2000/svg";
      const el = (name, attrs) => {
        const node = document.createElementNS(SVG_NS, name);
        for (const [k, v] of Object.entries(attrs || {})) node.setAttribute(k, v);
        return node;
      };

      function createScene(svg) {
        const uid = "line";
        const defs = el("defs");
        const gradId = `revealGrad-${uid}`;
        const maskId = `reveal-${uid}`;
        const grad = el("linearGradient", {
          id: gradId,
          gradientUnits: "userSpaceOnUse",
          x1: 0,
          y1: 0,
          x2: 1,
          y2: 0,
          spreadMethod: "pad",
        });
        grad.append(
          el("stop", { offset: "0", "stop-color": "#fff" }),
          el("stop", { offset: "1", "stop-color": "#fff", "stop-opacity": "0" })
        );
        const mask = el("mask", {
          id: maskId,
          maskUnits: "userSpaceOnUse",
          x: VIEW.x,
          y: VIEW.y,
          width: VIEW.w,
          height: VIEW.h,
        });
        mask.append(
          el("rect", {
            x: VIEW.x,
            y: VIEW.y,
            width: VIEW.w,
            height: VIEW.h,
            fill: `url(#${gradId})`,
          })
        );
        defs.append(grad, mask);

        const letterFilters = WORD.letters.map((_, i) => {
          const filter = el("filter", {
            id: `soften-${uid}-${i}`,
            x: "-60%",
            y: "-60%",
            width: "220%",
            height: "220%",
          });
          const blur = el("feGaussianBlur", { stdDeviation: "0" });
          filter.append(blur);
          defs.append(filter);
          return blur;
        });

        const underGroup = el("g", {
          transform: `translate(${UNDER_DX} ${UNDER_DY}) scale(${UNDER_SX} 1)`,
          mask: `url(#${maskId})`,
        });
        underGroup.append(el("path", { d: UNDER.d, fill: "currentColor" }));

        const letterNodes = WORD.letters.map((letter) => {
          const g = el("g");
          g.append(el("path", { d: letter.d, fill: "currentColor" }));
          return g;
        });

        const penGroup = el("g");
        PEN.paths.forEach((d) => penGroup.append(el("path", { d, fill: "currentColor" })));

        svg.replaceChildren(defs, underGroup, ...letterNodes, penGroup);

        return function apply(state) {
          grad.setAttribute("x1", state.revealX - cfg.strokeSoft);
          grad.setAttribute("x2", state.revealX);
          underGroup.setAttribute("opacity", cfg.strokeOpacity);
          state.letters.forEach((letter, i) => {
            const node = letterNodes[i];
            node.setAttribute("opacity", letter.opacity);
            node.setAttribute("transform", `translate(0 ${letter.dy})`);
            if (letter.blur > 0.01) {
              letterFilters[i].setAttribute("stdDeviation", letter.blur.toFixed(3));
              node.setAttribute("filter", `url(#soften-${uid}-${i})`);
            } else {
              node.removeAttribute("filter");
            }
          });
          const s = state.pen.scale;
          penGroup.setAttribute("opacity", state.pen.opacity);
          penGroup.setAttribute(
            "transform",
            `translate(${state.pen.x} ${state.pen.y}) rotate(${state.pen.rot}) scale(${s}) translate(${-TIP.x} ${-TIP.y})`
          );
        };
      }

      const apply = createScene(document.getElementById("design-svg"));
      const totalTime =
        cfg.startDelay + cfg.duration + Math.max(cfg.holdEnd, cfg.penExit);

      const trail = document.getElementById("trail");
      const rest = document.getElementById("rest");
      const design = document.getElementById("design");
      const build = document.getElementById("build");
      let trailReady = false;
      let restReady = false;
      let introActive = true;
      let introTimers = [];

      function clearIntroTimers() {
        introTimers.forEach((id) => clearTimeout(id));
        introTimers = [];
      }

      function later(fn, ms) {
        const id = setTimeout(fn, ms);
        introTimers.push(id);
        return id;
      }

      function setIcons(root, on) {
        root.dataset.hovered = on ? "true" : "false";
      }

      function showRest({ instant = false } = {}) {
        if (restReady) return;
        restReady = true;
        rest.setAttribute("aria-hidden", "false");
        if (instant) {
          rest.style.setProperty("--rest-fade", "0ms");
          rest.style.setProperty("--rest-stagger", "0ms");
          rest.dataset.entered = "true";
          return;
        }
        rest.style.removeProperty("--rest-fade");
        rest.style.removeProperty("--rest-stagger");
        requestAnimationFrame(() => {
          requestAnimationFrame(() => {
            rest.dataset.entered = "true";
          });
        });
      }

      function hideRest() {
        restReady = false;
        rest.dataset.entered = "false";
        rest.setAttribute("aria-hidden", "true");
        rest.style.removeProperty("--rest-fade");
        rest.style.removeProperty("--rest-stagger");
      }

      function showTrail({ instantLetters = false } = {}) {
        if (trailReady) return;
        trailReady = true;
        trail.hidden = false;
        trail.setAttribute("aria-hidden", "false");
        build.tabIndex = 0;

        if (instantLetters) {
          trail.style.setProperty("--char-fade", "0ms");
          trail.style.setProperty("--char-stagger", "0ms");
        } else {
          trail.style.removeProperty("--char-fade");
          trail.style.removeProperty("--char-stagger");
        }

        requestAnimationFrame(() => {
          requestAnimationFrame(() => {
            trail.dataset.entered = "true";
          });
        });
      }

      function hideTrail() {
        clearIntroTimers();
        trailReady = false;
        trail.dataset.entered = "false";
        trail.hidden = true;
        trail.setAttribute("aria-hidden", "true");
        trail.style.removeProperty("--char-fade");
        trail.style.removeProperty("--char-stagger");
        build.tabIndex = -1;
        setIcons(design, false);
        setIcons(build, false);
        hideRest();
      }

      /** Hover-icon intro: design stickers → build stickers → settle. No write-on. */
      function playIconIntroSequence({ reduceMotion = false } = {}) {
        clearIntroTimers();
        introActive = true;
        setIcons(design, false);
        setIcons(build, false);

        if (reduceMotion) {
          introActive = false;
          return;
        }

        const designHoldMs = 1100;
        const buildHoldMs = 1200;
        const betweenMs = 180;
        const startDelayMs = 400;

        later(() => {
          setIcons(design, true);
          later(() => {
            setIcons(design, false);
            later(() => {
              setIcons(build, true);
              later(() => {
                setIcons(build, false);
                introActive = false;
              }, buildHoldMs);
            }, betweenMs);
          }, designHoldMs);
        }, startDelayMs);
      }

      function bootSettled() {
        clock = totalTime;
        playing = false;
        apply(sample(clock));
        showTrail({ instantLetters: true });
        const reduce =
          typeof window.matchMedia === "function" &&
          window.matchMedia("(prefers-reduced-motion: reduce)").matches;
        // Copy is settled immediately — icon sequence waits for section reveal.
        showRest({ instant: true });
        const root = document.querySelector(".who-line");
        if (root) root.setAttribute("data-ready", "true");

        // Homepage holds the intro at opacity 0 until assets are ready, then
        // fades the section in (HomeScrollReveal). Start the design→build
        // flash only after that `.in-view`, so it isn't spent behind the veil.
        const section =
          root?.closest(".framer-mxkekt > *") || root?.parentElement || null;
        let iconsStarted = false;
        const startIcons = () => {
          if (disposed || iconsStarted) return;
          iconsStarted = true;
          playIconIntroSequence({ reduceMotion: reduce });
        };
        if (!section || section.classList.contains("in-view")) {
          startIcons();
        } else {
          const mo = new MutationObserver(() => {
            if (!section.classList.contains("in-view")) return;
            mo.disconnect();
            startIcons();
          });
          mo.observe(section, { attributes: true, attributeFilter: ["class"] });
          later(() => {
            mo.disconnect();
            startIcons();
          }, 5000);
        }
      }

      const INTRO_IMAGES = [
        "/who-line/assets/figma-logo.png",
        "/who-line/assets/color.svg",
        "/who-line/assets/claude.png",
        "/who-line/assets/cursor.png",
        "/who-line/assets/dev.png",
        "/who-line/assets/u-mask.svg",
      ];

      function loadImage(src) {
        return new Promise((resolve) => {
          const img = new Image();
          img.decoding = "async";
          img.onload = () => resolve();
          img.onerror = () => resolve();
          img.src = src;
        });
      }

      function waitForIntroAssets() {
        // Only wait on intro-critical faces — never document.fonts.ready,
        // which can stall on unrelated Framer/remote fonts.
        const fontLoads =
          document.fonts && typeof document.fonts.load === "function"
            ? Promise.all([
                document.fonts.load('400 18px "Switzer"'),
                document.fonts.load('400 18px "UglyDaveRegular"'),
              ]).catch(() => undefined)
            : Promise.resolve();

        const images = Promise.all(INTRO_IMAGES.map(loadImage));

        // Warm the hand-lettered face even if document.fonts is slow/missing.
        const fontFile = fetch("/who-line/assets/fonts/ugly-dave.woff2", {
          mode: "cors",
          credentials: "same-origin",
        })
          .then((r) => (r.ok ? r.arrayBuffer() : undefined))
          .catch(() => undefined);

        const ready = Promise.all([fontLoads, images, fontFile]);
        // Safety: never leave the hero blank forever on a hung request.
        const timeout = new Promise((resolve) => setTimeout(resolve, 4000));
        return Promise.race([ready, timeout]);
      }

      let clock = 0;
      let playing = false;

      // Keep a quiet rAF only so dblclick / future playback can resume.
      function frame() {
        if (playing) {
          clock = totalTime;
          playing = false;
          apply(sample(clock));
        }
        if (!disposed) requestAnimationFrame(frame);
      }
      requestAnimationFrame(frame);

      // Don't reveal or start design→build until intro assets are ready.
      waitForIntroAssets().then(() => {
        if (disposed) return;
        bootSettled();
      });

      document.body.addEventListener("dblclick", () => {
        clock = totalTime;
        playing = false;
        apply(sample(clock));
        if (!trailReady) showTrail({ instantLetters: true });
        else {
          trail.style.setProperty("--char-fade", "0ms");
          trail.style.setProperty("--char-stagger", "0ms");
          trail.dataset.entered = "true";
        }
        // Replay icon choreography; keep all copy visible.
        playIconIntroSequence({
          reduceMotion:
            typeof window.matchMedia === "function" &&
            window.matchMedia("(prefers-reduced-motion: reduce)").matches,
        });
      }, { signal: ac.signal });

      // ------------------------------------------------------------------
      // Hover for both lockups (disabled while the intro flash runs)
      // ------------------------------------------------------------------
      function bindHover(root) {
        const hit = root.querySelector(".lockup__hit");
        const set = (on) => {
          if (introActive) return;
          if (root.id === "build" && !trailReady) return;
          root.dataset.hovered = on ? "true" : "false";
        };
        const canHover =
          typeof window.matchMedia === "function" &&
          window.matchMedia("(hover: hover) and (pointer: fine)").matches;

        if (canHover) {
          hit.addEventListener("pointerenter", () => set(true));
          hit.addEventListener("pointerleave", () => set(false));
        } else {
          hit.addEventListener("click", (event) => {
            event.preventDefault();
            set(root.dataset.hovered !== "true");
          });
        }
        root.addEventListener("focus", () => set(true));
        root.addEventListener("blur", () => set(false));
      }

      bindHover(design);
      bindHover(build);

      document.querySelectorAll(".intro-lines__link").forEach((link) => {
        const badgeVariants = new Set(["tiktok", "lemon8", "trip"]);
        const previously = link.closest(".intro-lines__previously");
        const showsBadgeHint = badgeVariants.has(link.dataset.variant);

        link.addEventListener("pointerenter", () => {
          link.dataset.hovered = "true";
          if (showsBadgeHint && previously) previously.dataset.badgeHint = "true";
        });
        link.addEventListener("pointerleave", () => {
          link.dataset.hovered = "false";
          if (showsBadgeHint && previously) previously.dataset.badgeHint = "false";
        });
      });

      const params = new URLSearchParams(location.search);
      if (params.has("done") || params.has("hover") || params.has("design") || params.has("build")) {
        clearIntroTimers();
        clock = totalTime;
        playing = false;
        apply(sample(clock));
        introActive = false;
        if (!trailReady) showTrail({ instantLetters: true });
        showRest({ instant: true });
      }
      if (params.has("hover") || params.has("design")) {
        setIcons(design, true);
      }
      if (params.has("hover") || params.has("build")) {
        setIcons(build, true);
      }
    

  return () => {
    disposed = true;
    clearIntroTimers();
    ac.abort();
    document.querySelector(".who-line")?.removeAttribute("data-ready");
  };
}
